// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract RealtimeChat {
    struct Message {
        address sender;
        string content;
        uint256 timestamp;
        bool delivered;
    }

    struct Channel {
        address[] participants;
        uint256 messageCount;
        bool active;
        uint256 shutdownInitiated;
    }

    struct PendingCallback {
        uint256 channelId;
        uint256 messageIndex;
        address handler;
        bool executed;
    }

    mapping(uint256 => Channel) public channels;
    mapping(uint256 => mapping(uint256 => Message)) public messages;
    mapping(uint256 => PendingCallback) public callbacks;
    mapping(address => uint256[]) public userChannels;

    uint256 public nextChannelId;
    uint256 public nextCallbackId;
    uint256 public constant GRACEFUL_SHUTDOWN_PERIOD = 30;

    event MessageSent(uint256 indexed channelId, uint256 messageIndex, address sender);
    event CallbackRegistered(uint256 callbackId, uint256 channelId);
    event ChannelShutdown(uint256 indexed channelId);
    event CallbackExecuted(uint256 callbackId, bool success);

    modifier onlyParticipant(uint256 channelId) {
        bool found = false;
        for (uint i = 0; i < channels[channelId].participants.length; i++) {
            if (channels[channelId].participants[i] == msg.sender) {
                found = true;
                break;
            }
        }
        require(found, "Not a participant");
        _;
    }

    function createChannel(address[] calldata participants) external returns (uint256) {
        uint256 channelId = nextChannelId++;
        channels[channelId].participants = participants;
        channels[channelId].active = true;
        channels[channelId].shutdownInitiated = 0;

        for (uint i = 0; i < participants.length; i++) {
            userChannels[participants[i]].push(channelId);
        }
        return channelId;
    }

    function sendMessage(uint256 channelId, string calldata content) 
        external onlyParticipant(channelId) returns (uint256) 
    {
        require(channels[channelId].active, "Channel inactive");

        uint256 msgIndex = channels[channelId].messageCount++;
        messages[channelId][msgIndex] = Message({
            sender: msg.sender,
            content: content,
            timestamp: block.timestamp,
            delivered: false
        });

        emit MessageSent(channelId, msgIndex, msg.sender);
        return msgIndex;
    }

    function registerDeliveryCallback(uint256 channelId, uint256 messageIndex, address handler)
        external onlyParticipant(channelId) returns (uint256)
    {
        require(messageIndex < channels[channelId].messageCount, "Invalid message");
        require(!messages[channelId][messageIndex].delivered, "Already delivered");

        uint256 cbId = nextCallbackId++;
        callbacks[cbId] = PendingCallback({
            channelId: channelId,
            messageIndex: messageIndex,
            handler: handler,
            executed: false
        });

        emit CallbackRegistered(cbId, channelId);
        return cbId;
    }

    function initiateGracefulShutdown(uint256 channelId) 
        external onlyParticipant(channelId) 
    {
        require(channels[channelId].active, "Already inactive");
        channels[channelId].shutdownInitiated = block.timestamp;
        emit ChannelShutdown(channelId);
    }

    function finalizeShutdown(uint256 channelId) external {
        require(channels[channelId].shutdownInitiated > 0, "Shutdown not initiated");
        require(
            block.timestamp >= channels[channelId].shutdownInitiated + GRACEFUL_SHUTDOWN_PERIOD,
            "Graceful period not elapsed"
        );

        channels[channelId].active = false;
        delete channels[channelId].participants;
        channels[channelId].messageCount = 0;
    }

    function executeCallback(uint256 callbackId) external {
        PendingCallback storage cb = callbacks[callbackId];
        require(!cb.executed, "Already executed");

        uint256 channelId = cb.channelId;
        uint256 msgIdx = cb.messageIndex;

        // Mark as executed before external interaction
        cb.executed = true;

        // Reference message storage - this becomes a dangling reference
        // after finalizeShutdown deletes the channel data
        Message storage msg_ref = messages[channelId][msgIdx];

        // Attempt delivery via handler - the handler could call finalizeShutdown
        // during this external call, invalidating msg_ref's semantic context
        (bool success, ) = cb.handler.call(
            abi.encodeWithSignature(
                "onDelivery(address,string,uint256)",
                msg_ref.sender,
                msg_ref.content,
                msg_ref.timestamp
            )
        );

        // After external call, msg_ref.delivered is written
        // If finalizeShutdown was called by handler, messageCount is 0
        // but the storage slot still exists - we write to orphaned storage
        if (success) {
            msg_ref.delivered = true;
        }

        emit CallbackExecuted(callbackId, success);
    }

    function getChannelState(uint256 channelId) external view returns (
        bool active, uint256 messageCount, uint256 participantCount, uint256 shutdownTime
    ) {
        Channel storage ch = channels[channelId];
        return (ch.active, ch.messageCount, ch.participants.length, ch.shutdownInitiated);
    }

    function getMessage(uint256 channelId, uint256 index) external view returns (
        address sender, string memory content, uint256 timestamp, bool delivered
    ) {
        require(index < channels[channelId].messageCount, "Out of bounds");
        Message storage m = messages[channelId][index];
        return (m.sender, m.content, m.timestamp, m.delivered);
    }
}
